// Hand-written; qutegen never overwrites *_manual.go files.

// Package qtopengl binds QtOpenGL: shader programs, buffers, vertex array
// objects, textures and framebuffer objects. It is generated by cmd/qutegen
// from spec/.
//
// GL itself is called through qtgui.QOpenGLFunctions (from a context's
// Functions()), with the GL_* constants in package qtgui. Pointer arguments of
// GL calls are unsafe.Pointer: GL decides how much it reads from other
// arguments, so keep the memory alive for the call (and, for client-side
// arrays, until the draw).
package qtopengl
